head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getDisabled]<br/>파라미터에 맞게 특정 단위의 비활성화(disabled) 상태를 true/false 로 반환합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 type 파라미터값이 'all' 일때 비활성화(disabled) 상태를 조회할 Column 과 Cell 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Row 2 → setRowDisabled(true) / Column col1 → setColumnDisabled(true) / Cell(3,col4) → setCellDisabled(true) / 그 외 단위는 미설정 / [all 검증 예] Cell(2,col3)은 자체 미설정이나 상위 Row 2 disabled 로 all 조회 시 true (cell 단위 조회 시 false 와 대비)"', '', 'label1');

    // 조건 설정 (disabled/readonly Cell 을 배경색으로 구분: disabled=회색, readonly=연노랑)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList);

    // 각 단위별 disabled 설정 ('all' 종합 계산 검증을 위해 GridView/Row/Column/Cell 단위가 공존하도록 구성)
    // target1.setDisabled("grid", true);       // GridView 전체 단위
    target1.setRowDisabled(2, true);            // Row 2 단위
    target1.setColumnDisabled("col1", true);  // Column col1 단위 (ID)
    target1.setCellDisabled(3, "col4", true); // Cell(3,col4) 단위 (ID)
}



scwin.btn_getDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let colInfo = par_colInfo.getValue();

    // type 은 'all' 고정, type/rowIndex/colInfo(ID) 전달
    let rtn = target1.getDisabled("all", rowIndex, colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('all', " + rowIndex + ", '" + colInfo + "') : " + rtn);
}
